// Pocket storage index — record JAH-GPCS-FLASHDRIVE-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"capacity_gb": 128, "speed_mbs": 400, "price_usd": 20};
var value = (m.capacity_gb*m.speed_mbs/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-FLASHDRIVE-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-FLASHDRIVE-000001|' + value.toFixed(2) + ' storage index');

